WITH archived AS (
  SELECT * FROM payment_transactions WHERE is_archived_basket_reference = 1
)
SELECT 'archived_count' AS probe, COUNT(*) AS n FROM archived
UNION ALL
SELECT 'shared_card_ge3', COUNT(*) FROM archived a WHERE a.payment_method_fingerprint IN (
  SELECT payment_method_fingerprint FROM archived GROUP BY payment_method_fingerprint HAVING COUNT(DISTINCT customer_id) >= 3
)
UNION ALL
SELECT 'shared_device_ge3', COUNT(*) FROM archived a WHERE a.device_fingerprint IN (
  SELECT device_fingerprint FROM archived GROUP BY device_fingerprint HAVING COUNT(DISTINCT customer_id) >= 3
)
UNION ALL
SELECT 'card_device_pair_ge2cust', COUNT(*) FROM archived a WHERE (a.payment_method_fingerprint, a.device_fingerprint) IN (
  SELECT payment_method_fingerprint, device_fingerprint FROM archived GROUP BY payment_method_fingerprint, device_fingerprint HAVING COUNT(DISTINCT customer_id) >= 2
)
UNION ALL
SELECT 'coord_cluster_ge3cust', COUNT(*) FROM archived a WHERE (ROUND(a.observed_latitude,4), ROUND(a.observed_longitude,4)) IN (
  SELECT ROUND(observed_latitude,4), ROUND(observed_longitude,4) FROM archived GROUP BY ROUND(observed_latitude,4), ROUND(observed_longitude,4) HAVING COUNT(DISTINCT customer_id) >= 3
);
